package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

var inputString []string
var currentLine int

func readLine() string {
	line := inputString[currentLine]
	currentLine++
	return line
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		inputString = append(inputString, strings.TrimSpace(scanner.Text()))
