	diff := total - front

	if diff > back {
		fmt.Println(back + 1)
	} else {
		fmt.Println(diff)
	}
}

func parseLine() (int, int, int) {
	parts := strings.Split(readLine(), " ")
	total, _ := strconv.Atoi(parts[0])
	front, _ := strconv.Atoi(parts[1])
	back, _ := strconv.Atoi(parts[2])
	return total, front, back
}
